using CourseRegistration.Data;using CourseRegistration.Model;using CourseRegistration.Model.Enum;namespace CourseRegistration.Services;/// <summary>/// Handles enrollment, dropping, and FIFO waitlist promotion/// for a course offering./// </summary>public sealed class CourseRegistrationService(    RegistrationDbContext db,    ILogger<CourseRegistrationService> logger) : ICourseRegistrationService{    private const int DefaultOfferingId = 1;    // Protects operations within this service instance only.    private readonly object _sync = new();    /// <summary>Enrolls a learner in the default offering.</summary>    public RegistrationResult Enroll(int learnerId) =>        Enroll(DefaultOfferingId, learnerId);    /// <summary>Enrolls a learner or adds them to the waitlist.</summary>    public RegistrationResult Enroll(int offeringId, int learnerId)    {        lock (_sync)        {            var validationResult = ValidateEnrollment(offeringId, learnerId);            if (validationResult is not null)                return validationResult;            var offering = db.Offerings.Single(x => x.Id == offeringId);            var enrolledCount = db.Enrollments.Count(                x => x.OfferingId == offeringId);            return enrolledCount < offering.Capacity                ? EnrollImmediately(offeringId, learnerId)                : AddToWaitlist(offeringId, learnerId);        }    }    /// <summary>Drops a learner from the default offering.</summary>    public RegistrationResult Drop(int learnerId) =>        Drop(DefaultOfferingId, learnerId);    /// <summary>Drops an active enrollment and processes the waitlist.</summary>    public RegistrationResult Drop(int offeringId, int learnerId)    {        lock (_sync)        {            var validationResult = ValidateDrop(offeringId, learnerId);            if (validationResult is not null)                return validationResult;            var enrollment = FindEnrollment(offeringId, learnerId);            if (enrollment is null)                return RejectDrop(learnerId);            RemoveEnrollment(enrollment);            PromoteNextEligible(offeringId);            return new(                true,                RegistrationStatus.Enrolled,                "Enrollment dropped. Waitlist promotion processed.");        }    }    /// <summary>Validates that the offering and learner exist before a drop.</summary>    private RegistrationResult? ValidateDrop(int offeringId, int learnerId)    {        if (!db.Offerings.Any(x => x.Id == offeringId))            return Reject("Unknown offering.", RegistrationFailure.UnknownOffering);        if (!db.Learners.Any(x => x.Id == learnerId))            return Reject("Unknown learner.", RegistrationFailure.UnknownLearner);        return null;    }    /// <summary>Finds the learner's active enrollment in the specified offering.</summary>    private Enrollment? FindEnrollment(int offeringId, int learnerId)    {        return db.Enrollments.SingleOrDefault(x =>            x.OfferingId == offeringId &&            x.LearnerId == learnerId);    }    /// <summary>Logs and returns the failure result for a learner who is not enrolled.</summary>    private RegistrationResult RejectDrop(int learnerId)    {        logger.LogWarning(            "Drop rejected for learner {LearnerId}: no active enrollment",            learnerId);        return Reject(            "Learner is not currently enrolled; no seat was released.",            RegistrationFailure.NotEnrolled);    }    /// <summary>Removes the enrollment, saves the change, and logs the drop.</summary>    private void RemoveEnrollment(Enrollment enrollment)    {        db.Enrollments.Remove(enrollment);        db.SaveChanges();        logger.LogInformation(            "Learner {LearnerId} dropped offering {OfferingId}",            enrollment.LearnerId,            enrollment.OfferingId);    }    /// <summary>Gets the snapshot for the default offering.</summary>    public OfferingSnapshot GetSnapshot() =>        GetSnapshot(DefaultOfferingId)!;    /// <summary>Gets enrollment and waitlist details for an offering.</summary>    public OfferingSnapshot? GetSnapshot(int offeringId)    {        lock (_sync)        {            var offering = db.Offerings.SingleOrDefault(                x => x.Id == offeringId);            if (offering is null)                return null;            var enrolledLearners = db.Enrollments                .Where(x => x.OfferingId == offeringId)                .OrderBy(x => x.LearnerId)                .Select(x => x.LearnerId)                .ToArray();            var waitlistedLearners = db.WaitlistEntries                .Where(x => x.OfferingId == offeringId)                .OrderBy(x => x.Sequence)                .Select(x => x.LearnerId)                .ToArray();            return new OfferingSnapshot(                offering.Capacity,                enrolledLearners,                waitlistedLearners);        }    }    /// <summary>Validates the offering, learner, duplicate state, and prerequisite.</summary>    private RegistrationResult? ValidateEnrollment(int offeringId, int learnerId)    {        if (!db.Offerings.Any(x => x.Id == offeringId))            return Reject("Unknown offering.", RegistrationFailure.UnknownOffering);        var learner = db.Learners.SingleOrDefault(x => x.Id == learnerId);        if (learner is null)            return LogAndReject(                "Enrollment rejected: learner {LearnerId} does not exist",                learnerId,                "Unknown learner.",                RegistrationFailure.UnknownLearner);        var duplicateResult = ValidateDuplicateEnrollment(offeringId, learnerId);        if (duplicateResult is not null)            return duplicateResult;        if (!learner.HasPrerequisite)            return LogAndReject(                "Enrollment rejected for learner {LearnerId}: prerequisite not satisfied",                learnerId,                "Learner does not satisfy the prerequisite.",                RegistrationFailure.PrerequisiteNotMet);        return null;    }    /// <summary>Rejects learners who are already enrolled or waitlisted.</summary>    private RegistrationResult? ValidateDuplicateEnrollment(int offeringId, int learnerId)    {        if (db.Enrollments.Any(x =>                x.OfferingId == offeringId && x.LearnerId == learnerId))        {            return LogAndReject(                "Duplicate enrollment request for learner {LearnerId}",                learnerId,                "Learner is already enrolled.",                RegistrationFailure.DuplicateEnrollment);        }        if (db.WaitlistEntries.Any(x =>                x.OfferingId == offeringId && x.LearnerId == learnerId))        {            return LogAndReject(                "Duplicate waitlist request for learner {LearnerId}",                learnerId,                "Learner is already on the waitlist.",                RegistrationFailure.DuplicateWaitlistEntry);        }        return null;    }    /// <summary>Logs a registration rejection and creates its failure result.</summary>    private RegistrationResult LogAndReject(        string logMessage,        int learnerId,        string errorMessage,        RegistrationFailure failure)    {        logger.LogWarning(logMessage, learnerId);        return Reject(errorMessage, failure);    }    /// <summary>Promotes the earliest eligible waitlisted learner when capacity is available.</summary>    private void PromoteNextEligible(int offeringId)    {        if (!HasAvailableCapacity(offeringId))            return;        var candidate = FindNextEligibleLearner(offeringId);        if (candidate is null)        {            logger.LogInformation(                "No eligible waitlisted learner is available for promotion");            return;        }        PromoteLearner(candidate);    }    /// <summary>Determines whether the offering has an available seat.</summary>    private bool HasAvailableCapacity(int offeringId)    {        var offering = db.Offerings.Single(x => x.Id == offeringId);        var enrolledCount = db.Enrollments.Count(            x => x.OfferingId == offeringId);        return enrolledCount < offering.Capacity;    }    /// <summary>Finds the earliest waitlisted learner who satisfies the prerequisite.</summary>    private WaitlistEntry? FindNextEligibleLearner(int offeringId)    {        return (            from entry in db.WaitlistEntries            join learner in db.Learners                on entry.LearnerId equals learner.Id            where entry.OfferingId == offeringId                  && learner.HasPrerequisite            orderby entry.Sequence            select entry        ).FirstOrDefault();    }    /// <summary>Moves a waitlisted learner into the enrollment list.</summary>    private void PromoteLearner(WaitlistEntry candidate)    {        db.WaitlistEntries.Remove(candidate);        db.Enrollments.Add(new Enrollment        {            OfferingId = candidate.OfferingId,            LearnerId = candidate.LearnerId        });        db.SaveChanges();        logger.LogInformation(            "Waitlisted learner {LearnerId} promoted to offering {OfferingId}",            candidate.LearnerId,            candidate.OfferingId);    }    /// <summary>Creates and saves an enrollment, then returns its success result.</summary>    private RegistrationResult EnrollImmediately(        int offeringId,        int learnerId)    {        db.Enrollments.Add(new Enrollment        {            OfferingId = offeringId,            LearnerId = learnerId        });        db.SaveChanges();        logger.LogInformation(            "Learner {LearnerId} enrolled in offering {OfferingId}",            learnerId,            offeringId);        return new(            true,            RegistrationStatus.Enrolled,            "Enrollment successful.");    }    /// <summary>Adds and saves a learner at the end of the offering's waitlist.</summary>    private RegistrationResult AddToWaitlist(        int offeringId,        int learnerId)    {        var lastSequence = db.WaitlistEntries            .Where(x => x.OfferingId == offeringId)            .Select(x => (long?)x.Sequence)            .Max() ?? 0;        var nextSequence = lastSequence + 1;        db.WaitlistEntries.Add(new WaitlistEntry        {            OfferingId = offeringId,            LearnerId = learnerId,            Sequence = nextSequence        });        db.SaveChanges();        logger.LogInformation(             "Learner {LearnerId} added to waitlist at position {Position}",            learnerId,            nextSequence);        return new(            true,            RegistrationStatus.Waitlisted,            "Course is full; learner added to waitlist.");    }    /// <summary>Creates a rejected registration result with its failure reason.</summary>    private static RegistrationResult Reject(        string message,        RegistrationFailure failure) =>        new(false, RegistrationStatus.Rejected, message, failure);}